upstream mcp_fleet {
  server mcp-instance-1:8080;
  server mcp-instance-2:8080;
  server mcp-instance-3:8080;
}

upstream mcp_fleet {
  least_conn;
  server mcp-instance-1:8080;
  server mcp-instance-2:8080;
  server mcp-instance-3:8080;
}

upstream mcp_fleet {
  server mcp-instance-1:8080 weight=3;
  server mcp-instance-2:8080 weight=1;
}

upstream mcp_fleet {
  hash $http_x_mcp_session_id consistent;
  server mcp-instance-1:8080;
  server mcp-instance-2:8080;
  server mcp-instance-3:8080;
}

server {
  location /mcp/ {
    proxy_pass http://mcp_fleet;
    proxy_set_header X-MCP-Session-Id $http_x_mcp_session_id;
  }
}
